-- New store only; never applied to the legacy Drizzle database.
CREATE TABLE profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE devices (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), platform TEXT NOT NULL, UNIQUE(profile_id,id));
CREATE TABLE settings (profile_id TEXT PRIMARY KEY REFERENCES profiles(id), schema_version INTEGER NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), revision INTEGER NOT NULL CHECK(revision>=1));
CREATE TABLE device_preferences (profile_id TEXT NOT NULL, device_id TEXT NOT NULL, theme TEXT NOT NULL, playback_rate REAL NOT NULL, json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(profile_id,device_id), FOREIGN KEY(profile_id,device_id) REFERENCES devices(profile_id,id));
CREATE TABLE provider_configs (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), kind TEXT NOT NULL CHECK(kind IN ('llm','tts')), endpoint TEXT NOT NULL, model TEXT NOT NULL, voice TEXT, secret_ref TEXT, revision INTEGER NOT NULL, UNIQUE(profile_id,kind));
CREATE TABLE lexemes (id TEXT PRIMARY KEY, lemma TEXT NOT NULL, pos TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL CHECK(kind IN ('word','phrase')), UNIQUE(lemma,pos,kind));
CREATE TABLE word_books (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('baseline','study')), source TEXT NOT NULL, archived_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, revision INTEGER NOT NULL, UNIQUE(profile_id,id));
CREATE UNIQUE INDEX active_book_name ON word_books(profile_id,name,kind) WHERE archived_at IS NULL;
CREATE TABLE imports (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), source_name TEXT NOT NULL, format TEXT NOT NULL, kind TEXT NOT NULL, report_json TEXT NOT NULL CHECK(json_valid(report_json)), source_hash TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(profile_id,id));
CREATE TABLE book_entries (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), book_id TEXT NOT NULL, lexeme_id TEXT NOT NULL REFERENCES lexemes(id), raw TEXT NOT NULL, import_id TEXT, UNIQUE(book_id,lexeme_id), FOREIGN KEY(profile_id,book_id) REFERENCES word_books(profile_id,id), FOREIGN KEY(profile_id,import_id) REFERENCES imports(profile_id,id));
CREATE TABLE cards (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), lexeme_id TEXT NOT NULL REFERENCES lexemes(id), front TEXT NOT NULL, meaning TEXT NOT NULL DEFAULT '', example TEXT NOT NULL DEFAULT '', text_source TEXT NOT NULL, origin TEXT NOT NULL, suspended INTEGER NOT NULL DEFAULT 0 CHECK(suspended IN (0,1)), archived_at INTEGER, state TEXT NOT NULL CHECK(state IN ('new','learning','review','relearning')), due INTEGER NOT NULL, stability REAL NOT NULL CHECK(stability>=0), difficulty REAL NOT NULL CHECK(difficulty>=0 AND difficulty<=10), reps INTEGER NOT NULL CHECK(reps>=0), lapses INTEGER NOT NULL CHECK(lapses>=0 AND lapses<=reps), last_review INTEGER, elapsed_days INTEGER NOT NULL, scheduled_days INTEGER NOT NULL, learning_steps INTEGER NOT NULL, scheduler_version TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision>=1), UNIQUE(profile_id,lexeme_id), UNIQUE(profile_id,id), CHECK(archived_at IS NULL OR suspended=1));
CREATE INDEX cards_queue ON cards(profile_id,archived_at,suspended,due);
CREATE TABLE command_receipts (profile_id TEXT NOT NULL REFERENCES profiles(id), operation_id TEXT NOT NULL, command_type TEXT NOT NULL, request_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), completed_at INTEGER NOT NULL, PRIMARY KEY(profile_id,operation_id));
CREATE TABLE events (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), device_id TEXT, operation_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), type TEXT NOT NULL, schema_version INTEGER NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), occurred_at INTEGER NOT NULL, UNIQUE(profile_id,operation_id,ordinal), FOREIGN KEY(profile_id,device_id) REFERENCES devices(profile_id,id));
CREATE INDEX events_profile_type_time ON events(profile_id,type,occurred_at);
CREATE TABLE review_logs (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), card_id TEXT NOT NULL, operation_id TEXT NOT NULL, rating TEXT NOT NULL CHECK(rating IN ('again','hard','good','easy')), state_before TEXT NOT NULL, state_after TEXT NOT NULL, due_before INTEGER NOT NULL, due_after INTEGER NOT NULL, scheduler_version TEXT NOT NULL, reviewed_at INTEGER NOT NULL, duration_ms INTEGER NOT NULL CHECK(duration_ms>=0), metadata TEXT NOT NULL DEFAULT '{}', FOREIGN KEY(profile_id,card_id) REFERENCES cards(profile_id,id), UNIQUE(profile_id,operation_id));
CREATE INDEX reviews_profile_time ON review_logs(profile_id,reviewed_at);
CREATE INDEX reviews_card_time ON review_logs(card_id,reviewed_at);
CREATE TABLE articles (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), title TEXT NOT NULL, body TEXT NOT NULL, body_hash TEXT NOT NULL, genre TEXT NOT NULL, tier TEXT NOT NULL, prompt_version TEXT NOT NULL, model TEXT NOT NULL, provider_fingerprint TEXT NOT NULL, source TEXT NOT NULL, license TEXT, analysis_json TEXT NOT NULL CHECK(json_valid(analysis_json)), analyzer_version TEXT NOT NULL, experiment_version TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(profile_id,id));
CREATE INDEX articles_profile_time ON articles(profile_id,created_at);
CREATE TABLE article_targets (profile_id TEXT NOT NULL REFERENCES profiles(id), article_id TEXT NOT NULL, lexeme_id TEXT NOT NULL REFERENCES lexemes(id), role TEXT NOT NULL CHECK(role IN ('exposed','control')), occurrences INTEGER NOT NULL CHECK(occurrences>=0), selection_reason TEXT NOT NULL, PRIMARY KEY(article_id,lexeme_id), FOREIGN KEY(profile_id,article_id) REFERENCES articles(profile_id,id));
CREATE TABLE reading_sessions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), article_id TEXT NOT NULL, opened_at INTEGER NOT NULL, completed_at INTEGER, position INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(profile_id,article_id) REFERENCES articles(profile_id,id));
CREATE TABLE lexeme_marks (profile_id TEXT NOT NULL REFERENCES profiles(id), lexeme_id TEXT NOT NULL REFERENCES lexemes(id), status TEXT NOT NULL CHECK(status IN ('known','unknown')), marked_at INTEGER NOT NULL, revision INTEGER NOT NULL, PRIMARY KEY(profile_id,lexeme_id));
CREATE TABLE inbox (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), lexeme_id TEXT NOT NULL REFERENCES lexemes(id), article_id TEXT, body_hash TEXT, context_sentence TEXT NOT NULL, range_json TEXT, status TEXT NOT NULL CHECK(status IN ('pending','added','ignored')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, revision INTEGER NOT NULL, FOREIGN KEY(profile_id,article_id) REFERENCES articles(profile_id,id));
CREATE UNIQUE INDEX inbox_pending ON inbox(profile_id,lexeme_id) WHERE status='pending';
CREATE INDEX inbox_profile_status ON inbox(profile_id,status);
CREATE TABLE gloss_cache (profile_id TEXT NOT NULL REFERENCES profiles(id), lexeme_id TEXT NOT NULL REFERENCES lexemes(id), context_hash TEXT NOT NULL, prompt_version TEXT NOT NULL, provider_fingerprint TEXT NOT NULL, gloss_json TEXT NOT NULL CHECK(json_valid(gloss_json)), created_at INTEGER NOT NULL, PRIMARY KEY(profile_id,lexeme_id,context_hash,prompt_version,provider_fingerprint));
CREATE TABLE audio_assets (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), cache_key TEXT NOT NULL UNIQUE, text_hash TEXT NOT NULL, provider_fingerprint TEXT NOT NULL, model TEXT NOT NULL, voice TEXT NOT NULL, format TEXT NOT NULL, blob_key TEXT NOT NULL, duration REAL, chars INTEGER NOT NULL CHECK(chars>=0), created_at INTEGER NOT NULL, UNIQUE(profile_id,id));
CREATE TABLE article_audio_links (profile_id TEXT NOT NULL REFERENCES profiles(id), article_id TEXT NOT NULL, audio_id TEXT NOT NULL, PRIMARY KEY(profile_id,article_id,audio_id), FOREIGN KEY(profile_id,article_id) REFERENCES articles(profile_id,id), FOREIGN KEY(profile_id,audio_id) REFERENCES audio_assets(profile_id,id));
CREATE TABLE audio_reservations (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), operation_id TEXT NOT NULL, article_id TEXT NOT NULL, chars INTEGER NOT NULL CHECK(chars>=0), reserved_at INTEGER NOT NULL, outcome TEXT NOT NULL, UNIQUE(profile_id,operation_id), FOREIGN KEY(profile_id,article_id) REFERENCES articles(profile_id,id));
CREATE INDEX reservations_profile_time ON audio_reservations(profile_id,reserved_at);
CREATE TABLE audio_sessions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), article_id TEXT NOT NULL, audio_id TEXT, source TEXT NOT NULL CHECK(source IN ('remote','system','browser')), started_at INTEGER NOT NULL, completed_at INTEGER, rate REAL NOT NULL, FOREIGN KEY(profile_id,article_id) REFERENCES articles(profile_id,id), FOREIGN KEY(profile_id,audio_id) REFERENCES audio_assets(profile_id,id));
CREATE TABLE llm_calls (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), job_id TEXT, purpose TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, prompt_version TEXT NOT NULL, tokens_in INTEGER, tokens_out INTEGER, cost_usd REAL, latency_ms INTEGER NOT NULL, status TEXT NOT NULL, sanitized_error TEXT, ts INTEGER NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), operation_id TEXT NOT NULL, kind TEXT NOT NULL, phase TEXT NOT NULL, config_revision INTEGER NOT NULL, status TEXT NOT NULL, result_ref TEXT, error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(profile_id,operation_id));
CREATE TABLE legacy_imports (profile_id TEXT NOT NULL REFERENCES profiles(id), source_fingerprint TEXT NOT NULL, mapping_version TEXT NOT NULL, report_hash TEXT NOT NULL, completed_at INTEGER NOT NULL, PRIMARY KEY(profile_id,source_fingerprint,mapping_version));
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TRIGGER reviews_no_update BEFORE UPDATE ON review_logs BEGIN SELECT RAISE(ABORT,'review logs are append-only'); END;
CREATE TRIGGER reviews_no_delete BEFORE DELETE ON review_logs BEGIN SELECT RAISE(ABORT,'review logs are append-only'); END;
